// ============================================================
// 06_pangi_catalog_sync — Construcción de SQL
// ------------------------------------------------------------
// Toma las respuestas de los 3 endpoints públicos de Pangi y
// arma las sentencias de upsert. No escribe nada: solo construye.
//
// FUENTES (una llamada a speciality trae los 3 idiomas):
//   /api/common/speciality?lang=en   → especialidades + procedimientos
//   /api/common/countries            → catálogo curado de ciudades
//   /api/common/available-locations  → ciudades con médicos reales
// ============================================================

const runAt = new Date().toISOString();
const source = ($execution && $execution.mode === 'test') ? 'manual' : 'schedule';

// ── Sanitizadores ──
const q = (v) => (v === null || v === undefined || v === '')
  ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const qi = (v) => { const n = parseInt(v, 10); return Number.isFinite(n) ? String(n) : 'NULL'; };
const qb = (v) => (v === true || v === 'true') ? 'TRUE' : 'FALSE';

// sub_speciality, states y cities llegan como STRING con JSON adentro.
// Proctology llega como array real. Hay que soportar ambos.
const parseArr = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
  }
  return [];
};

const fail = (msg) => [{ json: { valid: false, runAt, source, error: msg,
  sqlLogFail: "INSERT INTO pangi_catalog_sync_log " +
    "(started_at, finished_at, status, trigger_source, error_message) VALUES (" +
    q(runAt) + "::timestamptz, NOW(), 'failed', " + q(source) + ", " + q(msg) + ");" } }];

// ── 1. Leer las tres respuestas ──
let rSpec, rCountries, rLocations;
try {
  rSpec      = $('🌐 API — Especialidades').first().json;
  rCountries = $('🌐 API — Países').first().json;
  rLocations = $('🌐 API — Ubicaciones Activas').first().json;
} catch (e) {
  return fail('No se pudieron leer las respuestas del API: ' + e.message);
}

// Doctores: se lee APARTE y sin abortar. Un fallo aquí NO debe impedir
// que se sincronicen especialidades, procedimientos y ciudades.
let rDoctors = null;
try { rDoctors = $('🌐 API — Doctores').first().json; } catch (e) { /* opcional */ }

const specData = (rSpec && Array.isArray(rSpec.data)) ? rSpec.data : [];
const cntData  = (rCountries && Array.isArray(rCountries.data)) ? rCountries.data : [];
const locData  = (rLocations && Array.isArray(rLocations.data)) ? rLocations.data : [];

// Guarda de plausibilidad: Pangi tiene 22 especialidades. Si llegan
// muchas menos, algo salió mal y NO se debe tocar el catálogo local.
const MIN_SPECIALTIES = 15;
if (specData.length < MIN_SPECIALTIES) {
  return fail('Respuesta implausible: ' + specData.length +
              ' especialidades (mínimo esperado ' + MIN_SPECIALTIES + ')');
}
if (cntData.length === 0 && locData.length === 0) {
  return fail('Ambas fuentes de ciudades vinieron vacías');
}

// ── 2. Especialidades ──
const specRows = [];
const procRows = [];
const seenProc = new Set();

for (const s of specData) {
  if (!s || !s._id || !s.name) continue;

  specRows.push('(' + [
    q(s._id), q(s.name), q(s.name_es), q(s.name_pt),
    qb(s.is_visible), qi(s.allow_number_of_procedure) === 'NULL' ? '1' : qi(s.allow_number_of_procedure),
    q(s.doc_en), q(s.doc_es), q(s.doc_pt), q(s.logo), q(runAt) + '::timestamptz'
  ].join(', ') + ')');

  // Procedimientos: arreglos PARALELOS alineados por posición.
  // Dental tiene 48 en inglés y 0 traducidos → name_es/name_pt en NULL.
  const en = parseArr(s.sub_speciality);
  const es = parseArr(s.sub_speciality_es);
  const pt = parseArr(s.sub_speciality_pt);

  for (let i = 0; i < en.length; i++) {
    const name = en[i];
    if (typeof name !== 'string' || !name) continue;
    // Dedup: ON CONFLICT no puede afectar la misma fila dos veces
    // dentro de un mismo INSERT.
    const key = s._id + '||' + name;
    if (seenProc.has(key)) continue;
    seenProc.add(key);

    procRows.push('(' + [
      q(s._id), String(i), q(name),
      q(es[i] !== undefined ? es[i] : null),
      q(pt[i] !== undefined ? pt[i] : null),
      q(runAt) + '::timestamptz'
    ].join(', ') + ')');
  }
}

if (specRows.length === 0) return fail('Ninguna especialidad válida tras el parseo');
if (procRows.length === 0) return fail('Ningún procedimiento válido tras el parseo');

// ── 3. Ciudades: unión de las dos fuentes ──
// countries           → in_catalog  (catálogo curado)
// available-locations → has_doctors (dónde hay médicos de verdad)
const cityMap = new Map();
const putCity = (code, cname, city, flag) => {
  if (!code || !city) return;
  const key = code + '||' + city;
  const prev = cityMap.get(key) || { code, cname, city, in_catalog: false, has_doctors: false };
  prev[flag] = true;
  if (cname) prev.cname = cname;
  cityMap.set(key, prev);
};

for (const c of cntData) {
  if (!c || !c.code) continue;
  for (const city of parseArr(c.cities)) {
    if (typeof city === 'string' && city) putCity(c.code, c.name, city, 'in_catalog');
  }
}
for (const l of locData) {
  const code = l && l.country ? l.country.code : null;
  const cname = l && l.country ? l.country.name : null;
  for (const city of (Array.isArray(l.cities) ? l.cities : [])) {
    if (typeof city === 'string' && city) putCity(code, cname, city, 'has_doctors');
  }
}

const cityRows = [];
for (const c of cityMap.values()) {
  cityRows.push('(' + [
    q(c.code), q(c.cname || c.code), q(c.city),
    qb(c.in_catalog), qb(c.has_doctors), q(runAt) + '::timestamptz'
  ].join(', ') + ')');
}
if (cityRows.length === 0) return fail('Ninguna ciudad válida tras el parseo');

// ── 4. Sentencias ──
const sqlSpecialties =
  'INSERT INTO pangi_specialties ' +
  '(pangi_id, name, name_es, name_pt, is_visible, allow_number_of_procedure, ' +
  ' doc_en, doc_es, doc_pt, logo, synced_at) VALUES\n' +
  specRows.join(',\n') + '\n' +
  'ON CONFLICT (pangi_id) DO UPDATE SET ' +
  'name = EXCLUDED.name, name_es = EXCLUDED.name_es, name_pt = EXCLUDED.name_pt, ' +
  'is_visible = EXCLUDED.is_visible, ' +
  'allow_number_of_procedure = EXCLUDED.allow_number_of_procedure, ' +
  'doc_en = EXCLUDED.doc_en, doc_es = EXCLUDED.doc_es, doc_pt = EXCLUDED.doc_pt, ' +
  'logo = EXCLUDED.logo, synced_at = EXCLUDED.synced_at;';

const sqlProcedures =
  'INSERT INTO pangi_procedures ' +
  '(specialty_pangi_id, position, name, name_es, name_pt, synced_at) VALUES\n' +
  procRows.join(',\n') + '\n' +
  'ON CONFLICT (specialty_pangi_id, name) DO UPDATE SET ' +
  'position = EXCLUDED.position, name_es = EXCLUDED.name_es, ' +
  'name_pt = EXCLUDED.name_pt, synced_at = EXCLUDED.synced_at;';

const sqlCities =
  'INSERT INTO pangi_cities ' +
  '(country_code, country_name, city, in_catalog, has_doctors, synced_at) VALUES\n' +
  cityRows.join(',\n') + '\n' +
  'ON CONFLICT (country_code, city) DO UPDATE SET ' +
  'country_name = EXCLUDED.country_name, in_catalog = EXCLUDED.in_catalog, ' +
  'has_doctors = EXCLUDED.has_doctors, synced_at = EXCLUDED.synced_at;';

// Limpieza + bitácora en UNA sola sentencia (CTE), para no depender
// de que el nodo Postgres acepte múltiples sentencias.
// Las especialidades NO se borran aquí: is_visible ya las oculta y
// borrarlas cascadearía procedimientos dentro del mismo statement.
// ── 3b. DOCTORES, CLÍNICAS Y SUS PROCEDIMIENTOS ─────────────
// Se validan y construyen de forma INDEPENDIENTE del catálogo.
// Si vienen mal, se emite una sentencia inerte (SELECT 0) en los tres
// nodos y la bitácora lo registra como 'skipped'. El catálogo sigue.
const MIN_DOCTORS = 20;   // hay 28; menos de 20 es implausible
const NOOP = 'SELECT 0 AS skipped';

let docRows = [], clinicRows = [], docProcRows = [];
let doctorsStatus = 'skipped';
let doctorsError  = null;

(() => {
  const dd = (rDoctors && Array.isArray(rDoctors.data) && rDoctors.data[0]
              && Array.isArray(rDoctors.data[0].data)) ? rDoctors.data[0].data : [];
  if (dd.length === 0) { doctorsError = 'respuesta de doctores vacía o con forma inesperada'; return; }
  if (dd.length < MIN_DOCTORS) {
    doctorsError = 'implausible: ' + dd.length + ' doctores (mínimo ' + MIN_DOCTORS + ')';
    return;
  }

  const seenClinic = new Set();
  const seenProc   = new Set();

  for (const x of dd) {
    if (!x || !x._id || !x.first_name) continue;

    // Modalidades desde appointment[].code
    const modes = Array.isArray(x.appointment)
      ? x.appointment.map(a => String((a && a.code) || '').toLowerCase()) : [];
    const hasInPerson = modes.includes('in_person');
    const hasOnline   = modes.includes('online') || modes.includes('video');

    const clinics = Array.isArray(x.all_clinic_address) ? x.all_clinic_address : [];

    // Agendable: presencial EXIGE clínica (date-slots pide clinic_address).
    // Video NO la exige: para eso existe slots-online.
    const acceptsInPerson = hasInPerson && clinics.length > 0;
    const bookable        = acceptsInPerson || hasOnline;

    // languages: solo 3 de 28 lo tienen. El segundo elemento del ejemplo
    // ('Spanish (Latin America)') NO trae code → se cae al name.
    const langs = Array.isArray(x.languages)
      ? x.languages.map(l => (l && (l.code || l.name)) || '').filter(Boolean).join(', ')
      : '';

    const degrees = Array.isArray(x.dr_degree) ? x.dr_degree.filter(Boolean).join(', ') : '';
    const yrs = (x.area_of_expertise && x.area_of_expertise.name) || null;

    docRows.push('(' + [
      q(x._id), q(x.first_name), q(x.last_name), q(x.designation),
      q(x.professional_title), q(x.gender), q(x.profile_pic), q(x.about),
      q(yrs), q(degrees), q(x.licence_number), q(langs),
      qb(acceptsInPerson), qb(hasOnline), qb(bookable),
      (Number.isFinite(parseFloat(x.averageRate)) ? String(parseFloat(x.averageRate)) : '0'),
      (qi(x.reviewCounts) === 'NULL' ? '0' : qi(x.reviewCounts)),
      qb(x.is_approve), q(x.status), q(x.practice_name), q(x.website),
      q(runAt) + '::timestamptz'
    ].join(', ') + ')');

    for (const c of clinics) {
      if (!c || !c._id || seenClinic.has(c._id)) continue;
      seenClinic.add(c._id);
      const cn = (c.country_name && c.country_name.name) || null;
      const lat = parseFloat(c.latitude), lng = parseFloat(c.longitude);
      clinicRows.push('(' + [
        q(c._id), q(x._id), q(c.clinic), q(c.name), q(c.address1), q(c.address2),
        q(c.city), q(c.state), q(cn),
        (Number.isFinite(lat) ? String(lat) : 'NULL'),
        (Number.isFinite(lng) ? String(lng) : 'NULL'),
        q(runAt) + '::timestamptz'
      ].join(', ') + ')');
    }

    // procedure[] → lo que ofrece y, además, la fuente del desplegable
    // "Motivo de la Visita" en la web (get-treatment-reason viene vacío
    // en TODOS los doctores, verificado).
    for (const p of (Array.isArray(x.procedure) ? x.procedure : [])) {
      const nm = p && p.name;
      if (typeof nm !== 'string' || !nm) continue;
      const key = x._id + '||' + nm;
      if (seenProc.has(key)) continue;   // ON CONFLICT no admite la misma fila 2 veces
      seenProc.add(key);
      docProcRows.push('(' + [
        q(x._id), q(nm), q(p.type || 'system'), q(runAt) + '::timestamptz'
      ].join(', ') + ')');
    }
  }

  if (docRows.length === 0) { doctorsError = 'ningún doctor válido tras el parseo'; return; }
  doctorsStatus = 'ok';
})();

const sqlDoctors = doctorsStatus !== 'ok' ? NOOP :
  'INSERT INTO pangi_doctors ' +
  '(pangi_id, first_name, last_name, designation, professional_title, gender, ' +
  ' profile_pic, about, years_experience, degrees, license_number, languages, ' +
  ' accepts_in_person, accepts_online, is_bookable, average_rate, review_count, ' +
  ' is_approve, status, practice_name, website, synced_at) VALUES\n' +
  docRows.join(',\n') + '\n' +
  'ON CONFLICT (pangi_id) DO UPDATE SET ' +
  'first_name = EXCLUDED.first_name, last_name = EXCLUDED.last_name, ' +
  'designation = EXCLUDED.designation, professional_title = EXCLUDED.professional_title, ' +
  'gender = EXCLUDED.gender, profile_pic = EXCLUDED.profile_pic, about = EXCLUDED.about, ' +
  'years_experience = EXCLUDED.years_experience, degrees = EXCLUDED.degrees, ' +
  'license_number = EXCLUDED.license_number, languages = EXCLUDED.languages, ' +
  'accepts_in_person = EXCLUDED.accepts_in_person, accepts_online = EXCLUDED.accepts_online, ' +
  'is_bookable = EXCLUDED.is_bookable, average_rate = EXCLUDED.average_rate, ' +
  'review_count = EXCLUDED.review_count, is_approve = EXCLUDED.is_approve, ' +
  'status = EXCLUDED.status, practice_name = EXCLUDED.practice_name, ' +
  'website = EXCLUDED.website, synced_at = EXCLUDED.synced_at;';

const sqlClinics = (doctorsStatus !== 'ok' || clinicRows.length === 0) ? NOOP :
  'INSERT INTO pangi_clinics ' +
  '(pangi_id, doctor_pangi_id, label, name, address1, address2, city, state, ' +
  ' country_name, latitude, longitude, synced_at) VALUES\n' +
  clinicRows.join(',\n') + '\n' +
  'ON CONFLICT (pangi_id) DO UPDATE SET ' +
  'doctor_pangi_id = EXCLUDED.doctor_pangi_id, label = EXCLUDED.label, ' +
  'name = EXCLUDED.name, address1 = EXCLUDED.address1, address2 = EXCLUDED.address2, ' +
  'city = EXCLUDED.city, state = EXCLUDED.state, country_name = EXCLUDED.country_name, ' +
  'latitude = EXCLUDED.latitude, longitude = EXCLUDED.longitude, ' +
  'synced_at = EXCLUDED.synced_at;';

const sqlDoctorProcedures = (doctorsStatus !== 'ok' || docProcRows.length === 0) ? NOOP :
  'INSERT INTO pangi_doctor_procedures (doctor_pangi_id, name, source, synced_at) VALUES\n' +
  docProcRows.join(',\n') + '\n' +
  'ON CONFLICT (doctor_pangi_id, name) DO UPDATE SET ' +
  'source = EXCLUDED.source, synced_at = EXCLUDED.synced_at;';

// Los doctores solo se limpian si su sincronización fue 'ok': de lo
// contrario se borrarían todos por no haberse refrescado.
const _delDoctors = doctorsStatus === 'ok'
  ? '), del_doc AS (  DELETE FROM pangi_doctors WHERE synced_at < ' + q(runAt) + '::timestamptz RETURNING 1'
  : '), del_doc AS (  SELECT 1 WHERE FALSE';

const sqlCleanupAndLog =
  'WITH del_proc AS (' +
  '  DELETE FROM pangi_procedures WHERE synced_at < ' + q(runAt) + '::timestamptz RETURNING 1' +
  '), del_city AS (' +
  '  DELETE FROM pangi_cities WHERE synced_at < ' + q(runAt) + '::timestamptz RETURNING 1' +
  _delDoctors +
  ') INSERT INTO pangi_catalog_sync_log ' +
  '(started_at, finished_at, status, specialties_seen, procedures_seen, ' +
  ' cities_seen, doctors_seen, clinics_seen, doctors_status, ' +
  ' rows_deleted, error_message, trigger_source) ' +
  'SELECT ' + q(runAt) + '::timestamptz, NOW(), ' +
  q(doctorsStatus === 'ok' ? 'ok' : 'partial') + ', ' +
  specRows.length + ', ' + procRows.length + ', ' + cityRows.length + ', ' +
  docRows.length + ', ' + clinicRows.length + ', ' + q(doctorsStatus) + ', ' +
  '(SELECT COUNT(*) FROM del_proc) + (SELECT COUNT(*) FROM del_city) + (SELECT COUNT(*) FROM del_doc), ' +
  q(doctorsError) + ', ' + q(source) + ';';

return [{ json: {
  valid: true, runAt, source,
  counts: { specialties: specRows.length, procedures: procRows.length, cities: cityRows.length,
            doctors: docRows.length, clinics: clinicRows.length, doctorProcedures: docProcRows.length },
  doctorsStatus, doctorsError,
  sqlSpecialties, sqlProcedures, sqlCities,
  sqlDoctors, sqlClinics, sqlDoctorProcedures,
  sqlCleanupAndLog
} }];
